import unittest
from dataclasses import FrozenInstanceError
from solution import Document, collect_assets


class CollectAssetsTests(unittest.TestCase):
    def test_depth_first_preorder_transitive_closure(self):
        documents = {
            "root": Document(b"r", ("a", "b")),
            "a": Document(b"a", ("c",)),
            "b": Document(b"b", ()),
            "c": Document(b"c", ()),
        }
        result = collect_assets(documents, "root")
        self.assertEqual(list(result), ["root", "a", "c", "b"])
        self.assertEqual(result, {"root": b"r", "a": b"a", "c": b"c", "b": b"b"})
        self.assertIsNot(result, documents)

    def test_cycles_and_repeated_links_are_visited_once(self):
        documents = {
            "a": Document(b"a", ("b", "b", "c")),
            "b": Document(b"b", ("a", "c")),
            "c": Document(b"c", ()),
        }
        result = collect_assets(documents, "a")
        self.assertEqual(list(result), ["a", "b", "c"])

    def test_missing_entry_and_transitive_link(self):
        with self.assertRaises(KeyError): collect_assets({}, "missing")
        with self.assertRaises(KeyError): collect_assets({"a": Document(b"a", ("missing",))}, "a")

    def test_document_validation_and_frozen(self):
        with self.assertRaises(TypeError): Document("bytes", ())
        with self.assertRaises(TypeError): Document(b"x", [])
        with self.assertRaises(TypeError): Document(b"x", (1,))
        with self.assertRaises(ValueError): Document(b"x", ("",))
        document = Document(b"x", ())
        with self.assertRaises(FrozenInstanceError): document.content = b"y"

    def test_function_validation(self):
        valid = {"x": Document(b"x", ())}
        for documents in ([], None, "x"):
            with self.assertRaises(TypeError): collect_assets(documents, "x")
        for entry in (None, 1):
            with self.assertRaises(TypeError): collect_assets(valid, entry)
        with self.assertRaises(ValueError): collect_assets(valid, "")
        with self.assertRaises(TypeError): collect_assets({1: Document(b"x", ())}, "x")
        with self.assertRaises(ValueError): collect_assets({"": Document(b"x", ())}, "x")
        with self.assertRaises(TypeError): collect_assets({"x": b"x"}, "x")

    def test_result_is_new_on_each_call(self):
        documents = {"x": Document(b"x", ())}
        first = collect_assets(documents, "x")
        second = collect_assets(documents, "x")
        self.assertIsNot(first, second)
        first["extra"] = b"e"
        self.assertEqual(second, {"x": b"x"})
        self.assertEqual(list(documents), ["x"])


if __name__ == "__main__":
    unittest.main()

